import java.io.*;import java.lang.reflect.*;import java.util.*;import org.prairielearn.api.PlatformApiPrecheck.Api;import org.prairielearn.api.PlatformApiPrecheck.Mismatch;
public class PublishedApi {public static void check(Api api)throws Exception {Class<?> a,b;try{a=api.type("A");b=api.type("B");}catch(Mismatch unavailable){throw new IllegalStateException("Teacher placement не адресовано: нужна ручная привязка, ошибка student API не установлена",unavailable);}api.expect(a.getSimpleName().equals("A")&&b.getSimpleName().equals("B")&&!a.isInterface()&&!b.isInterface(),"классы A/B",a+" / "+b);api.expect(b.getSuperclass()==a,"B extends A",b.getSuperclass().toString());Constructor<?> ctor;try{ctor=a.getDeclaredConstructor();}catch(NoSuchMethodException absent){api.expect(false,"данный A() с checked IOException",Arrays.toString(a.getDeclaredConstructors()));return;}var checked=Arrays.stream(ctor.getExceptionTypes()).filter(t->!RuntimeException.class.isAssignableFrom(t)&&!Error.class.isAssignableFrom(t)).toList();api.expect(!checked.isEmpty()&&checked.stream().allMatch(IOException.class::isAssignableFrom),"A() объявляет checked IOException в допустимой области",ctor.toString());
api.compiles("InheritanceClient","class InheritanceClient {A assign(B value){return value;}}",true);
}}

